<?php require_once __DIR__ . '/includes/init.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf(); $id=(int)($_POST['product_id']??0); if($id>0){$exists=db_one('SELECT id FROM wishlist WHERE user_id=? AND product_id=?',[(int)$_SESSION['user_id'],$id]); if($exists)db_query('DELETE FROM wishlist WHERE user_id=? AND product_id=?',[(int)$_SESSION['user_id'],$id]); else db_query('INSERT INTO wishlist (user_id,product_id) VALUES (?,?)',[(int)$_SESSION['user_id'],$id]);} redirect('wishlist.php');} $products=$wishlist_ids()?db_all(product_list_select().' WHERE p.id IN ('.implode(',',array_map('intval',wishlist_ids())).') ORDER BY p.name'):[]; $pageTitle='Wishlist'; require __DIR__.'/includes/header.php'; ?><main class="container page-section"><p class="eyebrow">Saved for later</p><h1>Your wishlist</h1><?php if(!$products): ?><div class="empty-state"><h3>Your wishlist is empty</h3><p>Save pieces you love while browsing the shop.</p><a class="btn btn-primary" href="<?=e(url('shop.php'))?>">Browse the shop</a></div><?php else: ?><form method="post"><?=csrf_field()?></form><?php render_product_grid($products,'Your wishlist is empty','Save pieces you love while browsing the shop.'); ?><?php endif; ?></main><?php require __DIR__.'/includes/footer.php'; ?>
